/**
 * frontend/src/components/Enrollment.jsx - VERSION PREMIUM ATTRACTIVE
 */

import React, { useState } from 'react';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#1E40AF',      // Bleu profond
  primaryLight: '#DBEAFE',
  accent: '#10B981',       // Vert clair attractif
  accentLight: '#A7F3D0',
  danger: '#EF4444',
  dangerLight: '#FEE2E2',
  textMain: '#0F172A',
  textMuted: '#64748B',
  border: '#CBD5E1',
  surface: '#FFFFFF',
  background: '#F1F5F9'
};

const Enrollment = ({ addNotification }) => {
  const [formData, setFormData] = useState({ name: '', email: '', level: '', filiere: '' });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const showMessage = (msg, type = 'info') => {
    setMessage(String(msg));
    setMessageType(type);
    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 5000);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    if (!selectedFile.type.startsWith("image/")) {
      showMessage("Veuillez sélectionner une image valide", "error");
      return;
    }

    setFile(selectedFile);
    const reader = new FileReader();
    reader.onload = (event) => {
      if (typeof event.target?.result === 'string') setPreview(event.target.result);
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const name = formData.name.trim();
    const email = formData.email?.trim() || null;
    const level = formData.level;
    const filiere = formData.filiere;

    if (!name || !file || !level || !filiere) {
      showMessage("Nom, image, niveau et filière sont requis", "error");
      return;
    }

    setLoading(true);
    try {
      showMessage("Envoi en cours...", "info");

      const response = await studentsAPI.enrollFromImage(name, email, file, level, filiere);

      if (response.success) {
        showMessage(`${response.data.name} a été enrôlé avec succès`, "success");
        addNotification(`${response.data.name} enrôlé`, 'success');

        setFormData({ name: '', email: '', level: '', filiere: '' });
        setFile(null);
        setPreview(null);
      } else {
        throw new Error(response.error || "Erreur inconnue");
      }
    } catch (err) {
      const errorMsg = err.message || "Erreur serveur";
      showMessage(`Erreur : ${errorMsg}`, "error");
      addNotification(`Erreur : ${errorMsg}`, 'error');
    }
    setLoading(false);
  };

  const messageColors = {
    success: { bg: COLORS.accentLight, text: '#166534', border: COLORS.accent },
    error: { bg: COLORS.dangerLight, text: COLORS.danger, border: COLORS.danger },
    info: { bg: COLORS.primaryLight, text: COLORS.primary, border: COLORS.primary }
  };

  const msgColor = messageColors[messageType];

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Header coloré */}
        <div style={styles.header}>
          <h2 style={styles.title}>Enrôlement d'un étudiant</h2>
        </div>

        {message && (
          <div style={{
            ...styles.message,
            backgroundColor: msgColor.bg,
            color: msgColor.text,
            borderLeft: `5px solid ${msgColor.border}`
          }}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Nom complet"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          />

          <input
            type="email"
            placeholder="Email (optionnel)"
            value={formData.email}
            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            style={styles.input}
            disabled={loading}
          />

          <div style={styles.selectRow}>
            <select
              value={formData.level}
              onChange={(e) => setFormData({ ...formData, level: e.target.value })}
              style={styles.select}
              disabled={loading}
              required
            >
              <option value="">Niveau</option>
              <option value="L1">L1</option>
              <option value="L2">L2</option>
              <option value="L3">L3</option>
              <option value="M1">M1</option>
              <option value="M2">M2</option>
              <option value="D1">D1</option>
              <option value="D2">D2</option>
            </select>

            <input
              type="text"
              placeholder="Filière"
              value={formData.filiere}
              onChange={(e) => setFormData({ ...formData, filiere: e.target.value })}
              style={styles.input}
              disabled={loading}
              required
            />
          </div>

          <div style={styles.fileArea}>
            <input
              type="file"
              accept="image/*"
              onChange={handleFileSelect}
              disabled={loading}
              required
              style={styles.fileInput}
            />
          </div>

          {preview && (
            <div style={styles.previewWrapper}>
              <img src={preview} alt="Prévisualisation" style={styles.preview} />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              ...styles.button,
              opacity: loading ? 0.8 : 1
            }}
          >
            {loading ? "Traitement en cours..." : "Enrôler l'étudiant"}
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  container: { 
    maxWidth: "560px", 
    margin: "40px auto", 
    padding: "20px" 
  },
  card: {
    backgroundColor: COLORS.surface,
    borderRadius: "24px",
    overflow: "hidden",
    boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.15)",
    border: `1px solid ${COLORS.border}`
  },
  header: {
    background: `linear-gradient(135deg, ${COLORS.primary} 0%, #3B82F6 100%)`,
    padding: "28px 35px",
    color: "white"
  },
  title: {
    margin: 0,
    fontSize: "28px",
    fontWeight: "700",
    textAlign: "center"
  },
  form: {
    padding: "35px",
    display: "flex",
    flexDirection: "column",
    gap: "20px"
  },
  input: {
    padding: "15px 18px",
    borderRadius: "12px",
    border: `1px solid ${COLORS.border}`,
    fontSize: "15.5px",
    outline: "none",
    transition: "0.3s",
    backgroundColor: "#F8FAFC"
  },
  selectRow: {
    display: "grid",
    gridTemplateColumns: "1fr 1.6fr",
    gap: "16px"
  },
  select: {
    padding: "15px 18px",
    borderRadius: "12px",
    border: `1px solid ${COLORS.border}`,
    fontSize: "15.5px",
    backgroundColor: "#F8FAFC",
    outline: "none"
  },
  fileArea: {
    padding: "12px 0"
  },
  fileInput: {
    width: "100%",
    padding: "16px",
    border: `2px dashed ${COLORS.accent}`,
    borderRadius: "14px",
    backgroundColor: "#F0FDF4",
    cursor: "pointer",
    fontSize: "15px"
  },
  previewWrapper: {
    borderRadius: "16px",
    overflow: "hidden",
    boxShadow: "0 15px 25px -5px rgba(16, 185, 129, 0.2)",
    border: `2px solid ${COLORS.accentLight}`
  },
  preview: {
    width: "100%",
    height: "auto",
    display: "block"
  },
  button: {
    marginTop: "10px",
    padding: "18px",
    fontSize: "17px",
    fontWeight: "600",
    border: "none",
    borderRadius: "14px",
    background: `linear-gradient(135deg, ${COLORS.primary} 0%, #2563EB 100%)`,
    color: "white",
    cursor: "pointer",
    transition: "all 0.3s ease",
    boxShadow: "0 10px 15px -3px rgba(30, 64, 175, 0.3)"
  },
  message: {
    padding: "16px 20px",
    borderRadius: "12px",
    fontSize: "15.5px",
    fontWeight: "500",
    marginBottom: "10px"
  }
};

export default Enrollment;
